DROP TABLE IF EXISTS decade_summary;

CREATE TABLE decade_summary (
  decade         int PRIMARY KEY,
  tracks         int NOT NULL,
  avg_popularity numeric(5,2)
);

INSERT INTO decade_summary (decade, tracks, avg_popularity)
SELECT (EXTRACT(YEAR FROM release_date)::int / 10) * 10,
       count(*),
       round(avg(popularity), 2)
FROM tracks
GROUP BY 1;

SELECT * FROM decade_summary ORDER BY decade;

ALTER TABLE tracks ADD COLUMN IF NOT EXISTS duration_min numeric(6,2);

UPDATE tracks
SET    duration_min = round(duration_ms / 60000.0, 2);

SELECT name, duration_ms, duration_min
FROM tracks
ORDER BY duration_min DESC
LIMIT 10;

INSERT INTO decade_summary (decade, tracks, avg_popularity)
VALUES (2030, 0, 0.00)
ON CONFLICT (decade) DO UPDATE
  SET tracks         = EXCLUDED.tracks,
      avg_popularity = EXCLUDED.avg_popularity;

SELECT * FROM decade_summary ORDER BY decade DESC LIMIT 5;

DROP MATERIALIZED VIEW IF EXISTS mv_genre_stats;

CREATE MATERIALIZED VIEW mv_genre_stats AS
SELECT g              AS genre,
       count(*)       AS artist_count,
       round(avg(a.popularity), 1) AS avg_popularity
FROM artists a
CROSS JOIN LATERAL unnest(a.genres) AS g
GROUP BY g;

CREATE UNIQUE INDEX mv_genre_stats_genre ON mv_genre_stats(genre);

REFRESH MATERIALIZED VIEW mv_genre_stats;

SELECT * FROM mv_genre_stats ORDER BY artist_count DESC LIMIT 20;

CREATE OR REPLACE PROCEDURE rebuild_decade_summary()
LANGUAGE plpgsql
AS $$
DECLARE
  affected int;
BEGIN
  CREATE TABLE IF NOT EXISTS decade_summary (
    decade         int PRIMARY KEY,
    tracks         int NOT NULL,
    avg_popularity numeric(5,2)
  );

  DELETE FROM decade_summary;

  INSERT INTO decade_summary (decade, tracks, avg_popularity)
  SELECT (EXTRACT(YEAR FROM release_date)::int / 10) * 10,
         count(*),
         round(avg(popularity), 2)
  FROM tracks
  GROUP BY 1;

  GET DIAGNOSTICS affected = ROW_COUNT;
  RAISE NOTICE 'decade_summary rebuilt with % rows', affected;
END;
$$;

CALL rebuild_decade_summary();

SELECT * FROM decade_summary ORDER BY decade;

DO $$
DECLARE
  cutoff      int := 80;
  hits        int;
  total       int;
BEGIN
  SELECT count(*) INTO hits  FROM tracks WHERE popularity >= cutoff;
  SELECT count(*) INTO total FROM tracks;

  RAISE NOTICE 'Tracks at popularity >= %: % of % (%.2f%%)',
    cutoff, hits, total, (100.0 * hits / total);
END;
$$;

DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT (EXTRACT(YEAR FROM release_date)::int / 10) * 10 AS decade,
           count(*) AS tracks
    FROM tracks
    GROUP BY 1
    ORDER BY 1
  LOOP
    RAISE NOTICE '% -> % tracks', r.decade, r.tracks;
  END LOOP;
END;
$$;

